using PrepareRenameResult = variant<Range, PrepareRenamePlaceholder, PrepareRenameDefaultBehavior>;

/// Signature help represents the signature of something
/// callable. There can be multiple signature but only one
/// active and only one active parameter.
struct SignatureHelp {
    /// One or more signatures.
    std::vector<SignatureInformation> signatures;

    /// The active signature. If omitted or the value lies outside the
    /// range of `signatures` the value defaults to zero or is ignored if
    /// the `SignatureHelp` has no signatures.
    ///
    /// Whenever possible implementors should make an active decision about
    /// the active signature and shouldn't rely on a default value.
    ///
    /// In future version of the protocol this property might become
    /// mandatory to better express this.
    optional<uinteger> active_signature = {};

    /// The active parameter of the active signature.
    ///
    /// If `null`, no parameter of the signature is active (for example a named
    /// argument that does not match any declared parameters). This is only valid
    /// if the client specifies the client capability
    /// `textDocument.signatureHelp.noActiveParameterSupport === true`
    ///
    /// If omitted or the value lies outside the range of
    /// `signatures[activeSignature].parameters` defaults to 0 if the active
    /// signature has parameters.
    ///
    /// If the active signature has no parameters it is ignored.
    ///
    /// In future version of the protocol this property might become
    /// mandatory (but still nullable) to better express the active parameter if
    /// the active signature does have any.
    ///
    /// Since version 3.16.0 the `SignatureInformation` itself provides a
    /// `activeParameter` property and it should be used instead of this one.
    optional<nullable<uinteger>> active_parameter = {};
};

/// Represents information about programming constructs like variables, classes,
/// interfaces etc.
struct SymbolInformation {
    /// The name of this symbol.
    string name;

    /// The kind of this symbol.
    SymbolKind kind;

    /// Tags for this symbol.
    ///
    /// @since 3.16.0
    optional<std::vector<SymbolTag>> tags = {};

    /// The name of the symbol containing this symbol. This information is for
    /// user interface purposes (e.g. to render a qualifier in the user interface
    /// if necessary). It can't be used to re-infer a hierarchy for the document
    /// symbols.
    optional<string> container_name = {};

    /// Indicates if this symbol is deprecated.
    ///
    /// @deprecated Use tags instead
    optional_bool deprecated = {};

    /// The location of this symbol. The location's range is used by a tool
    /// to reveal the location in the editor. If the symbol is selected in the
    /// tool the range's start information is used to position the cursor. So
    /// the range usually spans more than the actual symbol's name and does
    /// normally include things like visibility modifiers.
    ///
    /// The range doesn't have to denote a node range in the sense of an abstract
    /// syntax tree. It can therefore not be used to re-construct a hierarchy of
    /// the symbols.
    Location location;
};

