/// An event describing a change to a text document. If only a text is provided
/// it is considered to be the full content of the document.
using TextDocumentContentChangeEvent = variant<TextDocumentContentChangePartial, TextDocumentContentChangeWholeDocument>;

/// Describes textual changes on a text document. A TextDocumentEdit describes all changes
/// on a document version Si and after they are applied move the document to version Si+1.
/// So the creator of a TextDocumentEdit doesn't need to sort the array of edits or do any
/// kind of ordering. However the edits must be non overlapping.
struct TextDocumentEdit {
    /// The text document to change.
    OptionalVersionedTextDocumentIdentifier text_document;

    /// The edits to be applied.
    ///
    /// @since 3.16.0 - support for AnnotatedTextEdit. This is guarded using a
    /// client capability.
    ///
    /// @since 3.18.0 - support for SnippetTextEdit. This is guarded using a
    /// client capability.
    std::vector<variant<TextEdit, AnnotatedTextEdit, SnippetTextEdit>> edits;
};

