/// Represents a collection of {@link CompletionItem completion items} to be presented
/// in the editor.
struct CompletionList {
    /// This list it not complete. Further typing results in recomputing this list.
    ///
    /// Recomputed lists have all their items replaced (not appended) in the
    /// incomplete completion sessions.
    boolean is_incomplete;

    /// In many cases the items of an actual completion result share the same
    /// value for properties like `commitCharacters` or the range of a text
    /// edit. A completion list can therefore define item defaults which will
    /// be used if a completion item itself doesn't specify the value.
    ///
    /// If a completion list specifies a default value and a completion item
    /// also specifies a corresponding value, the rules for combining these are
    /// defined by `applyKinds` (if the client supports it), defaulting to
    /// ApplyKind.Replace.
    ///
    /// Servers are only allowed to return default values if the client
    /// signals support for this via the `completionList.itemDefaults`
    /// capability.
    ///
    /// @since 3.17.0
    optional<CompletionItemDefaults> item_defaults = {};

    /// Specifies how fields from a completion item should be combined with those
    /// from `completionList.itemDefaults`.
    ///
    /// If unspecified, all fields will be treated as ApplyKind.Replace.
    ///
    /// If a field's value is ApplyKind.Replace, the value from a completion item
    /// (if provided and not `null`) will always be used instead of the value
    /// from `completionItem.itemDefaults`.
    ///
    /// If a field's value is ApplyKind.Merge, the values will be merged using
    /// the rules defined against each field below.
    ///
    /// Servers are only allowed to return `applyKind` if the client
    /// signals support for this via the `completionList.applyKindSupport`
    /// capability.
    ///
    /// @since 3.18.0
    optional<CompletionItemApplyKinds> apply_kind = {};

    /// The completion items.
    std::vector<CompletionItem> items;
};

/// Represents a diagnostic, such as a compiler error or warning. Diagnostic objects
/// are only valid in the scope of a resource.
struct Diagnostic {
    /// The range at which the message applies
    Range range;

    /// The diagnostic's severity. To avoid interpretation mismatches when a
    /// server is used with different clients it is highly recommended that servers
    /// always provide a severity value.
    optional<DiagnosticSeverity> severity = {};

    /// The diagnostic's code, which usually appear in the user interface.
    optional<variant<integer, string>> code = {};

    /// An optional property to describe the error code.
    /// Requires the code field (above) to be present/not null.
    ///
    /// @since 3.16.0
    optional<CodeDescription> code_description = {};

    /// A human-readable string describing the source of this
    /// diagnostic, e.g. 'typescript' or 'super lint'. It usually
    /// appears in the user interface.
    optional<string> source = {};

    /// The diagnostic's message. It usually appears in the user interface.
    ///
    /// @since 3.18.0 - support for MarkupContent. This is guarded by the client
    /// capability `textDocument.diagnostic.markupMessageSupport`.
    variant<string, MarkupContent> message;

    /// Additional metadata about the diagnostic.
    ///
    /// @since 3.15.0
    optional<std::vector<DiagnosticTag>> tags = {};

    /// An array of related diagnostic information, e.g. when symbol-names within
    /// a scope collide all definitions can be marked via this property.
    optional<std::vector<DiagnosticRelatedInformation>> related_information = {};

    /// A data entry field that is preserved between a `textDocument/publishDiagnostics`
    /// notification and `textDocument/codeAction` request.
    ///
    /// @since 3.16.0
    optional<LSPAny> data = {};
};

/// The change text document notification's parameters.
struct DidChangeTextDocumentParams {
    /// The document that did change. The version number points
    /// to the version after all provided content changes have
    /// been applied.
    VersionedTextDocumentIdentifier text_document;

    /// The actual content changes. The content changes describe single state changes
    /// to the document. So if there are two content changes c1 (at array index 0) and
    /// c2 (at array index 1) for a document in state S then c1 moves the document from
    /// S to S' and c2 from S' to S''. So c1 is computed on the state S and c2 is computed
    /// on the state S'.
    ///
    /// To mirror the content of a document using change events use the following approach:
    /// - start with the same initial content
    /// - apply the 'textDocument/didChange' notifications in the order you receive them.
    /// - apply the `TextDocumentContentChangeEvent`s in a single notification in the order
    ///   you receive them.
    std::vector<TextDocumentContentChangeEvent> content_changes;
};

/// Describe options to be used when registered for text document change events.
struct DidChangeWatchedFilesRegistrationOptions {
    /// The watchers to register.
    std::vector<FileSystemWatcher> watchers;
};

